/* CSS PART 1 OF 4 */

/* DESIGN TOKENS */
:root {
  color-scheme: light;
  --color-ink: #202c32;
  --color-muted: #68757a;
  --color-paper: #f7f7f3;
  --color-white: #ffffff;
  --color-navy: #183746;
  --color-navy-deep: #102934;
  --color-orange: #c66b3d;
  --color-orange-hover: #a9522d;
  --color-border: #dce1dd;
  --color-surface: #edf0eb;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --container-width: 1200px;
  --container-gutter: 5vw;

  --radius-small: 4px;
  --radius-medium: 10px;
  --radius-large: 18px;

  --shadow-soft: 0 12px 35px rgba(24, 55, 70, 0.10);

  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --space-4: 2rem;
  --space-5: 3rem;
  --space-6: 4rem;
  --space-7: 6rem;

  --transition-fast: 180ms ease;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 6rem;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  cursor: pointer;
}

::selection {
  background: var(--color-orange);
  color: var(--color-white);
}

/* ACCESSIBILITY */
:focus-visible {
  outline: 3px solid var(--color-orange);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 1000;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--color-navy);
  color: var(--color-white);
  transform: translateY(-160%);
}

.skip-link:focus {
  transform: translateY(0);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--color-navy-deep);
  font-family: var(--font-display);
  font-weight: 500;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(2.8rem, 6vw, 5.7rem);
}

h2 {
  font-size: clamp(2.2rem, 4vw, 3.6rem);
}

h3 {
  font-size: clamp(1.4rem, 2vw, 1.9rem);
}

p {
  margin: 0 0 1.25rem;
}

p:last-child {
  margin-bottom: 0;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  margin-bottom: 1.25rem;
  color: var(--color-orange-hover);
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: currentColor;
  content: "";
}

.lead {
  max-width: 620px;
  color: var(--color-muted);
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.text-muted {
  color: var(--color-muted);
}

/* PAGE LAYOUT */
.container {
  width: min(
    calc(100% - var(--container-gutter) * 2),
    var(--container-width)
  );
  margin-inline: auto;
}

.section {
  padding-block: var(--space-7);
}

.section-heading {
  max-width: 760px;
  margin-bottom: var(--space-5);
}

.section-heading p {
  margin-top: 1.25rem;
  color: var(--color-muted);
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
  min-width: 0;
  color: var(--color-navy);
}

.site-brand img {
  width: auto;
  max-width: 190px;
  max-height: 62px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}

.brand-description {
  margin-top: 0.25rem;
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(1rem, 2.2vw, 2rem);
}

.primary-nav a:not(.button) {
  color: var(--color-ink);
  font-size: 0.85rem;
  font-weight: 700;
  transition: color var(--transition-fast);
}

.primary-nav a:not(.button):hover {
  color: var(--color-orange-hover);
}

.header-contact {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--color-navy);
  font-size: 0.85rem;
  font-weight: 800;
  white-space: nowrap;
}

/* REUSABLE BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 0.85rem 1.5rem;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: var(--color-orange);
  color: var(--color-white);
  font-size: 0.88rem;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;
  transition:
    background var(--transition-fast),
    border-color var(--transition-fast),
    color var(--transition-fast),
    transform var(--transition-fast);
}

.button:hover {
  transform: translateY(-2px);
  background: var(--color-orange-hover);
}

.button-secondary {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--color-white);
}

.button-secondary:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-navy);
}

.button-dark {
  background: var(--color-navy);
}

.button-dark:hover {
  background: var(--color-navy-deep);
}

.button:active {
  transform: translateY(0);
}

/* HERO */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--color-navy-deep);
  color: var(--color-white);
}

.hero-inner {
  display: grid;
  min-height: 650px;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: stretch;
}

.hero-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding-block: var(--space-7);
  padding-right: clamp(2rem, 5vw, 5rem);
}

.hero .eyebrow {
  color: #efb18d;
}

.hero h1 {
  max-width: 650px;
  color: var(--color-white);
}

.hero-description {
  max-width: 510px;
  margin-top: 1.5rem;
  color: rgba(255, 255, 255, 0.78);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin-top: 2rem;
}

.hero-credentials {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.78rem;
  font-weight: 700;
}

.hero-credentials span {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.hero-media {
  position: relative;
  min-height: 100%;
  background: #314b55;
}

.hero-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.hero-media::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(16, 41, 52, 0.3),
    transparent 45%
  );
  content: "";
  pointer-events: none;
}

.hero-image-caption {
  position: absolute;
  z-index: 2;
  right: 1.5rem;
  bottom: 1.5rem;
  max-width: 260px;
  padding: 0.85rem 1rem;
  border-left: 3px solid var(--color-orange);
  background: rgba(16, 41, 52, 0.9);
  color: var(--color-white);
  font-size: 0.75rem;
  line-height: 1.5;
}
