/* CSS PART 2 OF 4 */

/* TRUST AND COMPANY INTRODUCTION */
.intro-section {
  padding-block: var(--space-7);
  background: var(--color-white);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(3rem, 7vw, 7rem);
}

.intro-image {
  position: relative;
  min-height: 460px;
  overflow: hidden;
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}

.intro-image img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.intro-content {
  max-width: 650px;
}

.intro-content h2 {
  margin-bottom: 1.5rem;
}

.intro-content > p {
  color: var(--color-muted);
}

.experience-highlight {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  margin-top: 2rem;
  padding: 1.5rem;
  border-left: 3px solid var(--color-orange);
  background: var(--color-surface);
}

.experience-number {
  color: var(--color-orange-hover);
  font-family: var(--font-display);
  font-size: 3rem;
  line-height: 1;
  white-space: nowrap;
}

.experience-copy {
  color: var(--color-navy);
  font-size: 0.9rem;
  font-weight: 700;
}

/* SERVICES */
.services-section {
  padding-block: var(--space-7);
  background: var(--color-surface);
}

.services-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(3rem, 7vw, 7rem);
}

.services-intro {
  position: sticky;
  top: 2rem;
}

.services-intro h2 {
  margin-bottom: 1.25rem;
}

.services-intro p {
  color: var(--color-muted);
}

.services-list {
  border-top: 1px solid var(--color-border);
}

.service-item {
  display: grid;
  grid-template-columns: 55px 1fr;
  gap: 1.25rem;
  padding-block: 2rem;
  border-bottom: 1px solid var(--color-border);
}

.service-number {
  color: var(--color-orange-hover);
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.service-item h3 {
  margin-bottom: 0.6rem;
}

.service-item p {
  max-width: 520px;
  margin: 0;
  color: var(--color-muted);
  font-size: 0.95rem;
}

/* WORKING RELATIONSHIP / PROJECT OWNERSHIP */
.working-section {
  padding-block: var(--space-7);
  background: var(--color-navy);
  color: var(--color-white);
}

.working-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(3rem, 7vw, 7rem);
}

.working-content h2 {
  margin-bottom: 1.5rem;
  color: var(--color-white);
}

.working-content p {
  color: rgba(255, 255, 255, 0.76);
}

.working-principle {
  margin-top: 2rem;
  padding: 1.5rem 1.75rem;
  border-left: 3px solid var(--color-orange);
  background: rgba(255, 255, 255, 0.07);
  color: var(--color-white);
  font-family: var(--font-display);
  font-size: 1.35rem;
  line-height: 1.5;
}

.working-details {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.working-detail {
  padding-block: 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.working-detail h3 {
  margin-bottom: 0.5rem;
  color: #efb18d;
  font-size: 1.25rem;
}

.working-detail p {
  margin: 0;
  color: rgba(255, 255, 255, 0.75);
  font-size: 0.9rem;
}

/* ROOFING GUIDANCE */
.roofing-section {
  padding-block: var(--space-7);
  background: var(--color-white);
}

.roofing-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  align-items: center;
  gap: clamp(3rem, 7vw, 7rem);
}

.roofing-content h2 {
  margin-bottom: 1.5rem;
}

.roofing-content > p {
  color: var(--color-muted);
}

.roofing-signs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.85rem 1.5rem;
  margin-top: 2rem;
  padding: 0;
  list-style: none;
}

.roofing-signs li {
  position: relative;
  padding-left: 1.5rem;
  color: var(--color-ink);
  font-size: 0.9rem;
  font-weight: 600;
}

.roofing-signs li::before {
  position: absolute;
  top: 0.65em;
  left: 0;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-orange);
  content: "";
}

.roofing-image {
  position: relative;
  min-height: 460px;
  overflow: hidden;
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}

.roofing-image img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.roofing-image-caption {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  left: 1rem;
  padding: 1rem 1.25rem;
  background: rgba(16, 41, 52, 0.92);
  color: var(--color-white);
  font-size: 0.82rem;
}

/* COLORADO ROOFING PROCESS */
.process-section {
  padding-block: var(--space-7);
  background: var(--color-paper);
}

.process-heading {
  max-width: 760px;
  margin-bottom: var(--space-5);
}

.process-heading p {
  margin-top: 1rem;
  color: var(--color-muted);
}

.process-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.process-step {
  min-height: 220px;
  padding: 2rem 1.5rem;
  border-right: 1px solid var(--color-border);
}

.process-step:first-child {
  padding-left: 0;
}

.process-step:last-child {
  padding-right: 0;
  border-right: 0;
}

.process-step-number {
  display: block;
  margin-bottom: 2rem;
  color: var(--color-orange-hover);
  font-family: var(--font-display);
  font-size: 2.2rem;
  line-height: 1;
}

.process-step h3 {
  margin-bottom: 0.75rem;
  font-size: 1.3rem;
}

.process-step p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.88rem;
}

/* RECENT PROJECTS */
.projects-section {
  padding-block: var(--space-7);
  background: var(--color-white);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: var(--space-5);
}

.projects-heading h2 {
  max-width: 700px;
}

.projects-heading p {
  max-width: 340px;
  margin: 0;
  color: var(--color-muted);
  font-size: 0.95rem;
}

.project-gallery {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.project-item {
  min-width: 0;
}

.project-image {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--color-surface);
}

.project-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-item:hover .project-image img {
  transform: scale(1.035);
}

.project-info {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 1.25rem;
  border-bottom: 1px solid var(--color-border);
}

.project-info h3 {
  font-size: 1.35rem;
}

.project-info p {
  margin: 0.4rem 0 0;
  color: var(--color-muted);
  font-size: 0.85rem;
}

.project-category {
  flex-shrink: 0;
  padding: 0.4rem 0.65rem;
  border: 1px solid var(--color-border);
  color: var(--color-navy);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
